        { label: '故作震怒，命人立即整隊', action: () => { state.flags.metHeTao = true; state.flags.yunchengReputation += 4; state.quests.main_songjiang.progress = '表面催辦緝捕，暗中尋找示警機會'; goScene('case_files'); } }
