    if (type === 'route') { n.defense -= 88 + clues * 2; n.alarm = Math.max(0, n.alarm - 15); n.message = '陶宗旺、鄒潤與戴宗公開道路界線、路基坡度、橋涵位置、驛站距離與繞行出口，私設關卡和假路權無法再藏匿。'; }
    else if (type === 'bridge') { n.defense -= 94 + office * 2; n.momentum = Math.min(n.maxMomentum, n.momentum + 10); n.message = '杜遷、孟康與湯隆查驗橋臺、梁板、欄索承載、涵洞通水與材料批次，危橋偷工與遮掩裂縫失去操作空間。'; }
    else if (type === 'drainage') { n.defense -= 100 + office * 2; n.alarm = Math.max(0, n.alarm - 11); n.message = '陶宗旺、侯健與解珍帶隊清通邊溝、補強護坡、監測坍方並修補坑洞，故意堵水與雨毀封路被切斷。'; }
    else if (type === 'signage') { n.defense -= 106 + watchtower * 2; n.alarm = Math.max(0, n.alarm - 11); n.message = '蕭讓與樂和公開路況、橋涵承載、合理收費、夜行燈牌與安全繞行，路霸不能再靠黑暗與假告示設卡。'; }
    else if (type === 'rescue') { n.defense = 0; n.message = '裴宣與安道全公開定期養護、災時搶通順序、醫療救援、事故調查與損失補償；危橋路霸壟行網完全瓦解。'; }
    if (type !== 'rescue') n.defense = Math.max(1, n.defense);
